import { LitElement, html, unsafeCSS } from "lit";
import { property, state, query } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import { NysFormControlElement } from "@nysds/internals";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-combobox is used. Importing them here
// (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render. It
// also guarantees the clear/toggle nys-buttons upgrade, since their accessible
// name lands on nys-button's real inner <button>, which only exists once
// nys-button renders.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
import "@nysds/nys-icon";
import "@nysds/nys-button";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-combobox.scss?inline";

interface ComboboxOption {
  value: string;
  label: string;
  disabled?: boolean;
  group?: string;
}

/**
 * `<nys-combobox>` is a form-enabled combo box combining text input with a filterable dropdown.
 *
 * Features:
 * - Type to filter options
 * - Keyboard navigation (Arrow keys, Enter, Escape)
 * - Mouse and keyboard interaction
 * - Clears non-selected text on blur
 * - Clear button when value is selected
 * - Integrates with forms via ElementInternals
 * - Supports native <option> and <optgroup> elements
 * - Accessible per W3C ARIA Authoring Practices
 *
 * @slot description - Optional custom description content below the label.
 * @slot default - Options (<option>, <optgroup>) to populate the dropdown
 *
 * @fires nys-change - Fired when selection changes. Detail: `{ id, value }`.
 * @fires nys-input - Fired on input change. Detail: `{ id, value }`.
 * @fires nys-focus - Fired when combobox receives focus.
 * @fires nys-blur - Fired when combobox loses focus.
 *
 *
 * @example Basic
 * ```html
 * <nys-combobox label="Select your favorite fruit">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="cherry">Cherry</option>
 *   <option value="date">Date</option>
 *   <option value="elderberry">Elderberry</option>
 *   <option value="fig">Fig</option>
 *   <option value="grape">Grape</option>
 *   <option value="honeydew">Honeydew</option>
 *   <option value="kiwi">Kiwi</option>
 *   <option value="lemon">Lemon</option>
 *   <option value="mango">Mango</option>
 *   <option value="nectarine">Nectarine</option>
 *   <option value="orange">Orange</option>
 *   <option value="papaya">Papaya</option>
 *   <option value="quince">Quince</option>
 *   <option value="raspberry">Raspberry</option>
 *   <option value="strawberry">Strawberry</option>
 *   <option value="tangerine">Tangerine</option>
 *   <option value="watermelon">Watermelon</option>
 * </nys-combobox>
 * ```
 *
 * @example Default Value
 * ```html
 * <nys-combobox label="Select your favorite fruit" value="mango">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="mango" selected>Mango</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Option Group
 * ```html
 * <nys-combobox label="Select a fruit" description="Fruits organized by category">
 *   <optgroup label="Citrus">
 *     <option value="lemon">Lemon</option>
 *     <option value="lime">Lime</option>
 *     <option value="orange">Orange</option>
 *     <option value="grapefruit">Grapefruit</option>
 *     <option value="tangerine">Tangerine</option>
 *   </optgroup>
 *   <optgroup label="Berries">
 *     <option value="strawberry">Strawberry</option>
 *     <option value="blueberry">Blueberry</option>
 *     <option value="raspberry">Raspberry</option>
 *     <option value="blackberry">Blackberry</option>
 *     <option value="cranberry">Cranberry</option>
 *   </optgroup>
 *   <optgroup label="Tropical">
 *     <option value="mango">Mango</option>
 *     <option value="pineapple">Pineapple</option>
 *     <option value="papaya">Papaya</option>
 *     <option value="coconut">Coconut</option>
 *     <option value="passionfruit">Passionfruit</option>
 *   </optgroup>
 *   <optgroup label="Stone Fruits">
 *     <option value="peach">Peach</option>
 *     <option value="plum">Plum</option>
 *     <option value="cherry">Cherry</option>
 *     <option value="apricot">Apricot</option>
 *     <option value="nectarine">Nectarine</option>
 *   </optgroup>
 * </nys-combobox>
 * ```
 *
 * @example Disabled
 * ```html
 * <nys-combobox label="Select your favorite fruit" disabled>
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Required
 * ```html
 * <nys-combobox label="Select your favorite fruit" required>
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-combobox label="Select your favorite fruit" optional>
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Width Medium
 * ```html
 * <nys-combobox label="Select your favorite fruit" width="md">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Width Large
 * ```html
 * <nys-combobox label="Select your favorite fruit" width="lg">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Description
 * ```html
 * <nys-combobox label="Select your favorite fruit" description="Choose from the list of available fruits.">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```d
 *
 * @example Description Slot
 * ```html
 * <nys-combobox label="Select your favorite fruit">
 *   <label slot="description">This is a description slot</label>
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Error Message
 * ```html
 * <nys-combobox label="Select your favorite fruit" showError errorMessage="Please select a fruit">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="orange">Orange</option>
 *   <option value="strawberry">Strawberry</option>
 * </nys-combobox>
 * ```
 *
 * @example Disabled Options
 * ```html
 * <nys-combobox label="Select your favorite fruit" description="Some fruits are out of season">
 *   <option value="apple">Apple</option>
 *   <option value="banana">Banana</option>
 *   <option value="cherry" disabled>Cherry (Out of season)</option>
 *   <option value="mango">Mango</option>
 *   <option value="strawberry" disabled>Strawberry (Out of season)</option>
 *   <option value="orange">Orange</option>
 * </nys-combobox>
 * ```
 */
export class NysCombobox extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  @property({ type: String, reflect: true }) id = "";
  @property({ type: String, reflect: true }) name = "";
  @property({ type: String }) label = "";
  @property({ type: String }) description = "";
  @property({ type: String }) value = "";
  @property({ type: Boolean, reflect: true }) disabled = false;
  @property({ type: Boolean, reflect: true }) required = false;
  @property({ type: Boolean, reflect: true }) optional = false;
  @property({ type: String }) tooltip = "";
  @property({ type: String, reflect: true }) form: string | null = null;
  @property({ type: String, reflect: true }) width: "md" | "lg" | "full" =
    "full";
  @property({ type: Boolean, reflect: true }) inverted = false;
  @property({ type: Boolean, reflect: true }) showError = false;
  @property({ type: String }) errorMessage = "";

  @state() private _isOpen = false;
  @state() private _filterText = "";
  @state() private _highlightedIndex = -1;
  @state() private _options: ComboboxOption[] = [];
  @state() private _filteredOptions: ComboboxOption[] = [];
  @state() private _dropdownAbove = false;
  @state() private _announcement = "";

  @query("input") private _input!: HTMLInputElement;
  @query(".nys-combobox__listbox") private _listbox?: HTMLElement;

  private _originalErrorMessage = "";
  private _hasUserInteracted = false;
  private _selectedLabel = "";
  private _defaultValue = "";
  private _hasResolvedSlottedValue = false;

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */
  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this._originalErrorMessage = this.errorMessage ?? "";
    this.addEventListener("invalid", this._handleInvalid);
    document.addEventListener("click", this._handleDocumentClick);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("invalid", this._handleInvalid);
    document.removeEventListener("click", this._handleDocumentClick);
  }

  firstUpdated() {
    // Slotted options are read in `_handleSlotChange`, which the slot's
    // `slotchange` event fires once its nodes are assigned. It also resolves an
    // option marked `selected` into `value` and captures `_defaultValue`.
    this._setValue();
    this._defaultValue = this.value;
  }

  // Derive display state from `value` before rendering, not after, so Lit
  // doesn't have to schedule a second update (see lit.dev/msg/change-in-update).
  willUpdate(changedProperties: Map<string | number | symbol, unknown>) {
    if (changedProperties.has("value")) {
      const option = this._options.find((opt) => opt.value === this.value);
      this._selectedLabel = option ? option.label : "";
      this._filterText = this._selectedLabel;
    }
  }

  updated(changedProperties: Map<string | number | symbol, unknown>) {
    if (changedProperties.has("value")) {
      this._setValue();
    }

    if (changedProperties.has("_isOpen") && this._isOpen) {
      // Positioning measures the rendered listbox, so it has to wait for this
      // update to settle before it may flip `_dropdownAbove`.
      this.updateComplete.then(() => {
        this._positionDropdown();
        this._scrollToHighlighted();
      });
    }
  }

  /**
   * Slot handling
   * --------------------------------------------------------------------------
   */
  private _handleSlotChange() {
    const slot = this.shadowRoot?.querySelector(
      'slot:not([name="description"])',
    ) as HTMLSlotElement | null;

    if (!slot) return;

    const assignedElements = slot.assignedElements({ flatten: true });
    const options: ComboboxOption[] = [];
    let markupSelected = "";

    assignedElements.forEach((node) => {
      if (node.tagName === "OPTION") {
        const option = node as HTMLOptionElement;
        options.push({
          value: option.value,
          label: option.textContent?.trim() || option.value,
          disabled: option.disabled,
        });
        if (option.selected && !markupSelected) {
          markupSelected = option.value;
        }
      } else if (node.tagName === "OPTGROUP") {
        const group = node as HTMLOptGroupElement;
        const groupLabel = group.label;

        Array.from(group.children).forEach((child) => {
          if (child.tagName === "OPTION") {
            const option = child as HTMLOptionElement;
            options.push({
              value: option.value,
              label: option.textContent?.trim() || option.value,
              disabled: option.disabled || group.disabled,
              group: groupLabel,
            });
            if (option.selected && !markupSelected) {
              markupSelected = option.value;
            }
          }
        });
      }
    });

    this._options = options;
    this._filteredOptions = options;

    // The first time options arrive, adopt an option marked `selected` unless
    // an explicit value was already set, and use the result as the reset baseline.
    if (!this._hasResolvedSlottedValue) {
      this._hasResolvedSlottedValue = true;

      if (!this.value && markupSelected) {
        this.value = markupSelected;
      }
      this._defaultValue = this.value;
    }

    // Set initial display text if value exists
    if (this.value) {
      const option = this._options.find((opt) => opt.value === this.value);
      if (option) {
        this._selectedLabel = option.label;
        this._filterText = option.label;
      }
    }
  }

  /**
   * Form Integration
   * --------------------------------------------------------------------------
   */
  private _setValue() {
    this.setFormValue(this.value);
    this._manageRequire();
  }

  private _manageRequire() {
    const message = this.errorMessage || "This field is required";
    const isInvalid =
      this.required && (!this.value || this.value?.trim() === "");

    if (isInvalid) {
      this.setValidityFromState({ valueMissing: true }, message, this._input);
    } else {
      this.clearValidity();
      this._hasUserInteracted = false;
    }
  }

  private _setValidityMessage(message: string = "") {
    this.showError = !!message;

    if (this._originalErrorMessage?.trim() && message !== "") {
      this.errorMessage = this._originalErrorMessage;
    } else {
      this.errorMessage = message;
    }

    if (message) {
      this.setValidityFromState(
        { customError: true },
        this.errorMessage,
        this._input,
      );
    } else {
      this.clearValidity();
    }
  }

  private _validate() {
    if (!this._input) return;

    const validity = this._input.validity;
    let message = "";

    const isInvalid =
      this._input && !this._options.some((opt) => opt.value === this.value);

    if (validity.valueMissing || isInvalid) {
      message = "This field is required";
    } else {
      message = this._input.validationMessage;
    }

    this._setValidityMessage(message);
  }

  formResetCallback() {
    this.value = this._defaultValue;
    this._filterText = this._defaultValue
      ? (this._options.find((opt) => opt.value === this._defaultValue)?.label ??
        "")
      : "";
    this._selectedLabel = this._filterText;

    if (this._input) {
      this._input.value = this._filterText;
    }

    this.setFormValue(this.value);

    // Reset validation UI
    this.showError = false;
    this.errorMessage = "";
    this.clearValidity();

    this.requestUpdate();
  }
  checkValidity(): boolean {
    return this._input ? this._input.checkValidity() : true;
  }

  private _handleInvalid(event: Event) {
    event.preventDefault();
    this._hasUserInteracted = true;
    this._validate();

    if (this._input) {
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        const firstInvalidElement = elements.find(
          (element) =>
            typeof element.checkValidity === "function" &&
            !element.checkValidity(),
        );
        if (firstInvalidElement === this) {
          this._input.focus();
        }
      } else {
        this._input.focus();
      }
    }
  }

  /**
   * Dropdown positioning
   * --------------------------------------------------------------------------
   */
  private _positionDropdown() {
    if (!this._listbox || !this._input) return;

    const inputRect = this._input.getBoundingClientRect();
    const listboxHeight = this._listbox.offsetHeight;
    const viewportHeight = window.innerHeight;
    const spaceBelow = viewportHeight - inputRect.bottom;
    const spaceAbove = inputRect.top;

    // Show above if not enough space below and more space above
    this._dropdownAbove = spaceBelow < listboxHeight && spaceAbove > spaceBelow;
  }

  /**
   * Filtering
   * --------------------------------------------------------------------------
   */
  private _filterOptions(searchText: string) {
    if (!searchText) {
      this._filteredOptions = this._options;
      return;
    }

    const search = searchText.toLowerCase();
    this._filteredOptions = this._options.filter((option) =>
      option.label.toLowerCase().includes(search),
    );
  }

  /**
   * Keyboard navigation
   * --------------------------------------------------------------------------
   */
  private _scrollToHighlighted() {
    if (!this._listbox || this._highlightedIndex < 0) return;

    const highlighted = this._listbox.querySelector(
      `[data-index="${this._highlightedIndex}"]`,
    ) as HTMLElement;

    if (highlighted) {
      highlighted.scrollIntoView({ block: "nearest" });
    }
  }

  private _handleKeyDown(event: KeyboardEvent) {
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault();
        if (!this._isOpen) {
          this._openDropdown();
        } else {
          this._moveHighlight(1);
        }
        break;

      case "ArrowUp":
        event.preventDefault();
        if (!this._isOpen) {
          this._openDropdown();
        } else {
          this._moveHighlight(-1);
        }
        break;

      case "Enter":
        event.preventDefault();
        if (this._isOpen && this._highlightedIndex >= 0) {
          this._selectOption(this._filteredOptions[this._highlightedIndex]);
        }
        break;

      case "Escape":
        event.preventDefault();
        this._closeDropdown();
        this._filterText = this._selectedLabel;
        break;

      case "Tab":
        if (this._isOpen) {
          this._closeDropdown();
          this._filterText = this._selectedLabel;
        }
        break;
    }
  }

  private _moveHighlight(direction: number) {
    const enabledOptions = this._filteredOptions.filter((opt) => !opt.disabled);
    if (enabledOptions.length === 0) return;

    let newIndex = this._highlightedIndex + direction;

    // Wrap around
    if (newIndex < 0) {
      newIndex = this._filteredOptions.length - 1;
    } else if (newIndex >= this._filteredOptions.length) {
      newIndex = 0;
    }

    // Skip disabled options
    while (this._filteredOptions[newIndex]?.disabled) {
      newIndex += direction;
      if (newIndex < 0) newIndex = this._filteredOptions.length - 1;
      if (newIndex >= this._filteredOptions.length) newIndex = 0;
    }

    this._highlightedIndex = newIndex;
    this._scrollToHighlighted();

    const option = this._filteredOptions[newIndex];
    const prevOption = this._filteredOptions[newIndex - direction];
    const enabledFiltered = this._filteredOptions.filter(
      (opt) => !opt.disabled,
    );
    const position =
      enabledFiltered.findIndex((opt) => opt.value === option.value) + 1;
    const isSelected = option.value === this.value ? "selected" : "unselected";
    const groupChanged = option.group && option.group !== prevOption?.group;
    const groupPrefix = groupChanged ? `${option.group}, ` : "";
    this._announcement = `${groupPrefix} ${option.label} ${position} of ${enabledFiltered.length}, ${isSelected}`;
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */
  private _handleInput(event: Event) {
    const input = event.target as HTMLInputElement;
    this._filterText = input.value;
    this._filterOptions(this._filterText);

    if (!this._isOpen) {
      this._openDropdown();
    }

    this._highlightedIndex = 0;

    const count = this._filteredOptions.filter((opt) => !opt.disabled).length;
    this._announcement =
      count > 0 ? `${count} options available` : "No results found";

    if (this._hasUserInteracted) {
      this._validate();
    }

    this.dispatchEvent(
      new CustomEvent("nys-input", {
        detail: { id: this.id, value: this._filterText },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private _handleFocus() {
    this.dispatchEvent(
      new Event("nys-focus", { bubbles: true, composed: true }),
    );
  }

  private _handleBlur(event: FocusEvent) {
    // Check if focus moved to the listbox
    const relatedTarget = event.relatedTarget as HTMLElement;
    if (relatedTarget && this._listbox?.contains(relatedTarget)) {
      return;
    }

    // If no valid selection, clear the input
    if (!this.value || this._filterText !== this._selectedLabel) {
      this._filterText = this._selectedLabel;
      this._filterOptions("");
    }

    this._closeDropdown();

    if (!this._hasUserInteracted) {
      this._hasUserInteracted = true;
    }
    this._validate();

    this.dispatchEvent(
      new Event("nys-blur", { bubbles: true, composed: true }),
    );
  }

  private _handleDocumentClick = (event: MouseEvent) => {
    // Don't close if click is on the combobox host element or inside shadow DOM
    if (
      event.target === this ||
      this.shadowRoot?.contains(event.target as Node)
    ) {
      return;
    }
    this._closeDropdown();
  };

  private _handleIconClick() {
    if (this.disabled) return;

    if (this._isOpen) {
      this._closeDropdown();
    } else {
      this._input.focus();
      this._openDropdown();
    }
  }

  private _handleClearClick(event: Event) {
    event.stopPropagation();
    this.value = "";
    this._filterText = "";
    this._selectedLabel = "";
    this._filterOptions("");
    this.setFormValue("");
    this._closeDropdown();
    this._input.focus();

    this._handleChange();
  }

  private _handleOptionClick(option: ComboboxOption) {
    if (option.disabled) return;
    this._selectOption(option);
  }

  private _handleOptionMouseEnter(index: number) {
    this._highlightedIndex = index;
  }

  private _selectOption(option: ComboboxOption) {
    this.value = option.value;
    this._selectedLabel = option.label;
    this._filterText = option.label;
    this.setFormValue(this.value);
    this._input.focus();
    this._closeDropdown();
    this._filterOptions("");

    this._setValidityMessage("");

    if (this._hasUserInteracted) {
      this._validate();
    }

    this._handleChange();
  }

  private _handleChange() {
    this.dispatchEvent(
      new CustomEvent("nys-change", {
        detail: { id: this.id, value: this.value },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private _openDropdown() {
    this._isOpen = true;
    this._highlightedIndex = this._filteredOptions.findIndex(
      (opt) => opt.value === this.value,
    );
    if (this._highlightedIndex < 0) this._highlightedIndex = 0;
  }

  private _closeDropdown() {
    this._isOpen = false;
    this._highlightedIndex = -1;
  }

  /**
   * Render helpers
   * --------------------------------------------------------------------------
   */
  private _renderOptions() {
    let currentGroup = "";
    const elements: any[] = [];

    this._filteredOptions.forEach((option, index) => {
      if (option.group && option.group !== currentGroup) {
        currentGroup = option.group;
        elements.push(html`
          <div class="nys-combobox__optgroup" role="presentation">
            ${option.group}
          </div>
        `);
      }

      const isFocused = index === this._highlightedIndex;
      const isSelected = option.value === this.value;

      elements.push(html`
        <div
          class="nys-combobox__option ${isFocused
            ? "nys-combobox__option--focused"
            : ""} ${isSelected ? "nys-combobox__option--selected" : ""}"
          role="option"
          id="${this.id}--option-${index}"
          data-index="${index}"
          aria-selected="${isSelected}"
          aria-disabled="${option.disabled || false}"
          ?disabled=${option.disabled}
          @click=${() => this._handleOptionClick(option)}
          @mouseenter=${() => this._handleOptionMouseEnter(index)}
        >
          ${option.label}
        </div>
      `);
    });

    if (elements.length === 0) {
      return html`
        <div class="nys-combobox__no-results" role="option">
          No results found
        </div>
      `;
    }

    return elements;
  }

  render() {
    return html`
      <div class="nys-combobox">
        <nys-label
          id="${this.id}--label"
          label=${this.label}
          description=${this.description}
          flag=${this.required ? "required" : this.optional ? "optional" : ""}
          tooltip=${this.tooltip}
          ?inverted=${this.inverted}
        >
          <slot name="description" slot="description">${this.description}</slot>
        </nys-label>
        <div
          class="nys-combobox__container ${this._isOpen
            ? "nys-combobox__container--open"
            : ""}"
        >
          <div class="nys-combobox__input-wrapper">
            <input
              class="nys-combobox__input"
              type="text"
              role="combobox"
              aria-autocomplete="list"
              aria-expanded="${this._isOpen}"
              aria-controls="${this.id}--listbox"
              aria-activedescendant="${this._highlightedIndex >= 0
                ? `${this.id}--option-${this._highlightedIndex}`
                : ""}"
              name=${this.name}
              id=${this.id + "--native"}
              ?disabled=${this.disabled}
              ?required=${this.required}
              aria-required=${this.required}
              aria-disabled="${this.disabled}"
              aria-labelledby=${ifDefined(
                this.label ? this.id + "--label" : undefined,
              )}
              aria-label=${ifDefined(
                !this.label && this.description ? this.description : undefined,
              )}
              aria-invalid=${this.showError ? "true" : "false"}
              aria-errormessage=${this.id + "--error"}
              aria-describedby=${ifDefined(
                this.showError ? this.id + "--error" : undefined,
              )}
              .value=${this._filterText}
              form=${ifDefined(this.form || undefined)}
              @input=${this._handleInput}
              @focus="${this._handleFocus}"
              @blur="${this._handleBlur}"
              @keydown="${this._handleKeyDown}"
            />
            <div class="nys-combobox__buttons">
              ${this.value
                ? html`
                    <nys-button
                      class="nys-combobox__clear"
                      label="Clear selection"
                      variant="ghost"
                      size="sm"
                      circle
                      @nys-click=${this._handleClearClick}
                      ?disabled=${this.disabled}
                    >
                      <nys-icon
                        slot="suffix-icon"
                        size="20"
                        name="close"
                      ></nys-icon>
                    </nys-button>
                  `
                : ""}
              <nys-button
                class="nys-combobox__chevron"
                label="Toggle dropdown"
                variant="ghost"
                size="sm"
                circle
                @nys-click=${this._handleIconClick}
                ?disabled=${this.disabled}
              >
                <nys-icon
                  slot="suffix-icon"
                  size="20"
                  name="chevron_down"
                ></nys-icon>
              </nys-button>
            </div>
          </div>
          ${this._isOpen
            ? html`
                <div
                  class="nys-combobox__listbox ${this._dropdownAbove
                    ? "nys-combobox__listbox--above"
                    : ""}"
                  id="${this.id}--listbox"
                  role="listbox"
                  tabindex="-1"
                >
                  ${this._renderOptions()}
                </div>
              `
            : ""}
        </div>
        <slot
          style="display: none;"
          @slotchange=${this._handleSlotChange}
        ></slot>
        <nys-errormessage
          id=${this.id + "--error"}
          ?showError=${this.showError}
          errorMessage=${this.errorMessage}
        ></nys-errormessage>
        <div
          aria-live="polite"
          aria-atomic="true"
          style="position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;"
        >
          ${this._announcement}
        </div>
      </div>
    `;
  }
}

if (!customElements.get("nys-combobox")) {
  customElements.define("nys-combobox", NysCombobox);
}
