import { LitElement, html, unsafeCSS } from "lit";
import { property } from "lit/decorators.js";
import { ifDefined } from "lit/directives/if-defined.js";
import { NysFormControlElement } from "@nysds/internals";
import { NysOption } from "./nys-option";
// These internal elements are rendered inside this component's shadow DOM, so
// they must be registered whenever nys-select is used. Importing them here
// (intentional side effect) guarantees the visible label and error message —
// which the accessible name/error association depends on — always render.
// nys-icon renders the chevron-down indicator.
import "@nysds/nys-label";
import "@nysds/nys-errormessage";
import "@nysds/nys-icon";
// @ts-ignore: SCSS module imported via bundler as inline
import styles from "./nys-select.scss?inline";

/**
 * A dropdown for selecting a single option from a list. Supports native `<option>` and `<optgroup>` elements.
 * Form-associated with validation via ElementInternals.
 *
 * Use when users must choose one option from 7+ items. For fewer options, consider `nys-radiobutton`.
 * For multiple selections, use `nys-checkbox` group instead.
 *
 * @summary Dropdown select for choosing one option from a list.
 * @element nys-select
 *
 * @slot - Default slot for `<option>` and `<optgroup>` elements.
 * @slot description - Custom HTML description content below the label.
 *
 * @fires nys-change - Fired when selection changes. Detail: `{id, value}`.
 * @fires nys-focus - Fired when select gains focus.
 * @fires nys-blur - Fired when select loses focus. Triggers validation.
 *
 * @example Basic
 * ```html
 *  <nys-select label="Select your favorite borough" id="borough">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Default value
 * ```html
 * <nys-select label="Select your favorite borough" id="borough">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn" selected></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Option Group
 * ```html
 * <nys-select
 * label="Which New York State service are you contacting us about?"
 * description="This is for demo purposes and the list might not be exhaustive."
 * >
 *   <optgroup label="Transportation Services">
 *     <option value="mta">MTA / Public Transit</option>
 *     <option value="dmv">Department of Motor Vehicles (DMV)</option>
 *     <option value="highway">Highway Maintenance</option>
 *   </optgroup>
 *   <optgroup label="Health & Human Services">
 *     <option value="medicaid">Medicaid / Health Insurance</option>
 *     <option value="mental-health">Mental Health Support</option>
 *     <option value="child-family">Child and Family Services</option>
 *   </optgroup>
 *   <optgroup label="Public Safety">
 *     <option value="state-police">State Police</option>
 *     <option value="emergency-management">Emergency Management</option>
 *     <option value="fire-safety">Fire Safety</option>
 *   </optgroup>
 *   <optgroup label="Environment & Energy">
 *     <option value="environmental-conservation">
 *       Environmental Conservation
 *     </option>
 *     <option value="clean-energy">Clean Energy Programs</option>
 *     <option value="waste-management">Waste Management</option>
 *   </optgroup>
 * </nys-select>
 * ```
 * @example Disabled
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" disabled>
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Disabled Option
 * ```html
 * <nys-select label="Select your favorite borough" id="borough">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island" disabled></option>
 *   <option value="queens" label="Queens" disabled></option>
 * </nys-select>
 * ```
 *
 * @example Required
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" required>
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Optional
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" optional>
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Width small
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" width="sm">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Width medium
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" width="md">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Width large
 * ```html
 * <nys-select label="Select your favorite borough" id="borough" width="lg">
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Slotted Description
 * ```html
 * <nys-select label="Select your favorite borough" id="borough">
 *   <label slot="description">This is a slotted description</label>
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 * ```
 *
 * @example Error Message
 * <nys-select label="Select your favorite borough" id="borough" errorMessage="You did not select a borough" showError>
 *   <option value="bronx" label="The Bronx"></option>
 *   <option value="brooklyn" label="Brooklyn"></option>
 *   <option value="manhattan" label="Manhattan"></option>
 *   <option value="staten_island" label="Staten Island"></option>
 *   <option value="queens" label="Queens"></option>
 * </nys-select>
 */

export class NysSelect extends NysFormControlElement {
  static styles = unsafeCSS(styles);
  static shadowRootOptions = {
    ...LitElement.shadowRootOptions,
    delegatesFocus: true,
  };

  /** Unique identifier. Auto-generated if not provided. */
  @property({ type: String, reflect: true }) id = "";

  /** Name for form submission. */
  @property({ type: String, reflect: true }) name = "";

  /** Visible label text. Required for accessibility. */
  @property({ type: String }) label = "";

  /** Helper text below label. Use slot for custom HTML. */
  @property({ type: String }) description = "";

  /** Accessible label. Used as a fallback when `label` is not provided. */
  @property({ type: String }) ariaLabel = "";

  /** Currently selected option value. */
  @property({ type: String }) value = "";

  /** Prevents interaction. */
  @property({ type: Boolean, reflect: true }) disabled = false;

  /** Marks as required. Shows "Required" flag and validates on blur. */
  @property({ type: Boolean, reflect: true }) required = false;

  /** Shows "Optional" flag. Use when most fields are required. */
  @property({ type: Boolean, reflect: true }) optional = false;

  /** Tooltip text shown on hover/focus of info icon. */
  @property({ type: String }) tooltip = "";

  /** Form `id` to associate with when select is outside form element. */
  @property({ type: String, reflect: true }) form: string | null = null;

  /** Adjusts colors for dark backgrounds. */
  @property({ type: Boolean, reflect: true }) inverted = false;

  /** Shows error message when true. Set by validation or manually. */
  @property({ type: Boolean, reflect: true }) showError = false;

  /** Error message text. Shown only when `showError` is true. */
  @property({ type: String }) errorMessage = "";

  /**
   * Select width: `sm` (88px), `md` (200px), `lg` (384px), `full` (100%, default).
   * @default "full"
   */
  @property({ type: String, reflect: true }) width:
    | "sm"
    | "md"
    | "lg"
    | "full" = "full";

  private _originalErrorMessage = "";

  private _hasUserInteracted = false; // need this flag for "eager mode"

  /**
   * Lifecycle methods
   * --------------------------------------------------------------------------
   * Form association, ElementInternals, and id generation are provided by
   * NysFormControlElement (@nysds/internals).
   */

  connectedCallback() {
    // super.connectedCallback() (NysFormControlElement) assigns an id when one
    // is not provided and reflects default semantics.
    super.connectedCallback();
    this._originalErrorMessage = this.errorMessage ?? "";
    this.addEventListener("invalid", this._handleInvalid);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this.removeEventListener("invalid", this._handleInvalid);
  }

  firstUpdated() {
    // Slotted options are read in `_handleSlotChange`, which the slot's
    // `slotchange` event fires once its nodes are assigned. Doing it here
    // instead would set `value` after the update completed, forcing Lit to
    // schedule a second render (see lit.dev/msg/change-in-update).

    // This ensures our element always participates in the form
    this._setValue();
  }

  private _handleSlotChange() {
    const slot = this.shadowRoot?.querySelector(
      'slot:not([name="description"])',
    ) as HTMLSlotElement | null;
    const select = this.shadowRoot?.querySelector("select");

    if (!slot || !select) return;

    // Clean up any previously cloned <option> or <optgroup> elements so we don't get duplicates
    Array.from(select.children).forEach((child) => {
      if (!(child as HTMLElement).hasAttribute("data-native")) {
        child.remove();
      }
    });

    const assignedElements = slot.assignedElements({ flatten: true });

    assignedElements.forEach((node) => {
      // ---- Handle <nys-option> ---- (May consider removing this since depreciated since 2.0 release)
      if (node instanceof NysOption) {
        const optionElement = document.createElement("option");
        optionElement.value = node.value;
        optionElement.textContent =
          node.label || node.textContent?.trim() || "";
        optionElement.disabled = node.disabled;
        optionElement.selected = node.selected;
        select.appendChild(optionElement);
        return;
      }

      // ---- Handle native <option> ----
      if (node.tagName === "OPTION") {
        const original = node as HTMLOptionElement;
        const optionClone = original.cloneNode(true) as HTMLOptionElement;

        optionClone.disabled = original.disabled;
        optionClone.selected = original.selected;

        select.appendChild(optionClone);
        return;
      }

      // ---- Handle <optgroup> ----
      if (node.tagName === "OPTGROUP") {
        const groupClone = document.createElement("optgroup");
        groupClone.label = (node as HTMLOptGroupElement).label;
        if ((node as HTMLOptGroupElement).disabled) {
          groupClone.disabled = true;
        }

        // iterate children inside optgroup (could be nys-option or native option)
        Array.from(node.children).forEach((child) => {
          if (child instanceof NysOption) {
            const option = document.createElement("option");
            option.value = child.value;
            option.textContent = child.label || child.textContent?.trim() || "";
            option.disabled = child.disabled;
            option.selected = child.selected;
            groupClone.appendChild(option);
          } else if (child.tagName === "OPTION") {
            const optionClone = child.cloneNode(true) as HTMLOptionElement;
            groupClone.appendChild(optionClone);
          }
        });

        select.appendChild(groupClone);
        return;
      }
    });

    // Sync selected state into the component value. Re-cloning resets the
    // native selection, so keep the current value whenever it still matches an
    // option and only fall back to whatever the markup marked as selected.
    const keepsCurrentValue =
      !!this.value &&
      Array.from(select.options).some((o) => o.value === this.value);

    if (keepsCurrentValue) {
      select.value = this.value;
      return;
    }

    const selectedOption = Array.from(select.options).find((o) => o.selected);

    if (selectedOption) {
      this.value = selectedOption.value;
      this.setFormValue(this.value);
    }
  }

  /**
   * Form Integration
   * --------------------------------------------------------------------------
   */

  private _setValue() {
    this.setFormValue(this.value);
    this._manageRequire(); // Check validation when value is set
  }

  private _manageRequire() {
    const select = this.shadowRoot?.querySelector("select");
    if (!select) return;

    const message = this.errorMessage || "This field is required.";
    const isInvalid = this.required && !this.value;

    if (isInvalid) {
      this.setValidityFromState({ valueMissing: true }, message, select);
    } else {
      this.clearValidity();
      this._hasUserInteracted = false; // Reset the interaction flag, make lazy again
    }
  }

  private _setValidityMessage(message: string = "") {
    const select = this.shadowRoot?.querySelector("select");
    if (!select) return;

    // Toggle the HTML <div> tag error message
    this.showError = !!message;

    // If user sets errorMessage, this will always override the native validation message
    if (this._originalErrorMessage?.trim() && message !== "") {
      this.errorMessage = this._originalErrorMessage;
    } else {
      this.errorMessage = message;
    }

    if (message) {
      this.setValidityFromState(
        { customError: true },
        this.errorMessage,
        select,
      );
    } else {
      this.clearValidity();
    }
  }

  private _validate() {
    const select = this.shadowRoot?.querySelector("select");
    if (!select) return;

    // Get the native validation state
    let message = select.validationMessage;
    this._manageRequire(); // Makes sure the required state is checked

    this._setValidityMessage(message);
  }

  // This callback is automatically called when the parent form is reset.
  public formResetCallback() {
    this.value = "";
    const select = this.shadowRoot?.querySelector("select");
    if (select) {
      select.value = "";
      Array.from(select.options).forEach((other) => (other.selected = false));
    }

    // Reset validation UI
    this.showError = false;
    this.errorMessage = "";
    this.clearValidity();

    // Re-render UI
    this.requestUpdate();
  }

  /**
   * Functions
   * --------------------------------------------------------------------------
   */
  // This helper function is called to perform the element's native validation.
  checkValidity(): boolean {
    const select = this.shadowRoot?.querySelector("select");
    return select ? select.checkValidity() : true;
  }

  private _handleInvalid(event: Event) {
    event.preventDefault();
    this._hasUserInteracted = true; // Start aggressive mode due to form submission
    this._validate();
    this.showError = true;

    const select = this.shadowRoot?.querySelector("select");
    if (select) {
      // Focus only if this is the first invalid element (top-down approach)
      const form = this.internals?.form;
      if (form) {
        const elements = Array.from(form.elements) as Array<
          HTMLElement & { checkValidity?: () => boolean }
        >;
        // Find the first element in the form that is invalid
        const firstInvalidElement = elements.find(
          (element) =>
            typeof element.checkValidity === "function" &&
            !element.checkValidity(),
        );
        if (firstInvalidElement === this) {
          select.focus();
        }
      } else {
        // If not part of a form, simply focus.
        select.focus();
      }
    }
  }

  /**
   * Event Handlers
   * --------------------------------------------------------------------------
   */

  // Handle change event to bubble up selected value
  private _handleChange(e: Event) {
    const select = e.target as HTMLSelectElement;
    this.value = select.value;
    this.setFormValue(this.value);

    // Clear error immediately if value is now valid
    if (this.required && this.value) {
      this.showError = false;
      this.errorMessage = "";
      this.clearValidity();
    }

    // Validate aggressively if the user has already interacted
    if (this._hasUserInteracted) {
      this._validate();
    }

    this.dispatchEvent(
      new CustomEvent("nys-change", {
        detail: { id: this.id, value: this.value },
        bubbles: true,
        composed: true,
      }),
    );
  }

  // Handle focus event
  private _handleFocus() {
    this.dispatchEvent(
      new Event("nys-focus", { bubbles: true, composed: true }),
    );
  }

  // Handle blur event
  private _handleBlur() {
    if (!this._hasUserInteracted) {
      this._hasUserInteracted = true;
    }
    this._validate();
    this.dispatchEvent(
      new Event("nys-blur", { bubbles: true, composed: true }),
    );
  }

  // Check if the current value matches any option, and if so, set it as selected
  updated(changedProperties: Map<string, unknown>): void {
    super.updated(changedProperties);

    // This ensures the value is set correctly after the component renders
    if (changedProperties.has("value")) {
      const selectElement = this.shadowRoot?.querySelector("select");
      if (selectElement) {
        selectElement.value = this.value;
      }
      this._setValue();
    }
  }

  render() {
    return html`
      <div class="nys-select">
        <nys-label
          id="${this.id}--label"
          label=${this.label}
          description=${this.description}
          flag=${this.required ? "required" : this.optional ? "optional" : ""}
          tooltip=${this.tooltip}
          ?inverted=${this.inverted}
        >
          <slot name="description" slot="description">${this.description}</slot>
        </nys-label>
        <div class="nys-select__selectwrapper">
          <select
            class="nys-select__select"
            name=${this.name}
            id=${this.id + "--native"}
            form=${ifDefined(this.form || undefined)}
            ?disabled=${this.disabled}
            ?required=${this.required}
            aria-disabled="${this.disabled}"
            aria-labelledby=${ifDefined(
              this.label ? this.id + "--label" : undefined,
            )}
            aria-label=${ifDefined(
              !this.label && this.ariaLabel ? this.ariaLabel : undefined,
            )}
            aria-invalid=${this.showError ? "true" : "false"}
            aria-errormessage=${this.id + "--error"}
            aria-describedby=${ifDefined(
              this.showError ? this.id + "--error" : undefined,
            )}
            .value=${this.value}
            @focus="${this._handleFocus}"
            @blur="${this._handleBlur}"
            @change="${this._handleChange}"
          >
            <option data-native hidden disabled value=""></option>
          </select>
          <slot
            style="display: none;"
            @slotchange=${this._handleSlotChange}
          ></slot>
          <nys-icon
            name="chevron_down"
            size="2xl"
            class="nys-select__icon"
          ></nys-icon>
        </div>
        <nys-errormessage
          id=${this.id + "--error"}
          ?showError=${this.showError}
          errorMessage=${this.errorMessage}
        ></nys-errormessage>
      </div>
    `;
  }
}

if (!customElements.get("nys-select")) {
  customElements.define("nys-select", NysSelect);
}
